 * Merge one customer into another, reassigning all invoices.
 * @param {Array<any>} customers
 * @param {Array<any>} invoices
 * @param {string} fromId
 * @param {string} intoId
 * @returns {{ ok: true, value: { customers: Array<any>, invoices: Array<any> } } | { ok: false, error: string }}
